const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const furnaceCreek = ee.Geometry.Point(-116.8679, 36.4608); // Approximate coordinates for Furnace Creek Visitor Center
  const startDate = '2013-06-30T00:00:00';
  const endDate = '2013-07-01T00:00:00'; // End of June 30th

  // 2. Data Acquisition & Check
  const era5Collection = ee.ImageCollection("ECMWF/ERA5_LAND/HOURLY")
    .filterDate(startDate, endDate)
    .filterBounds(furnaceCreek)
    .select('temperature_2m'); // Select 2m air temperature band

  const collectionSize = await era5Collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No ERA5-Land hourly data found for June 30, 2013, at Furnace Creek.");
    console.log("C1");
    return;
  }
  console.log(`Hourly images for June 30, 2013: ${collectionSize}`);

  // 3. Processing
  // Convert Kelvin to Celsius: K - 273.15
  const era5Celsius = era5Collection.map(function(image) {
    return image.subtract(273.15).copyProperties(image, ['system:time_start']);
  });

  // Get the maximum temperature over the 24-hour period
  const maxTempImage = era5Celsius.reduce(ee.Reducer.max());

  // Check if maxTempImage is empty (though unlikely after collection size check)
  const bands = await maxTempImage.bandNames().getInfo();
  if (!bands || bands.length === 0) {
    console.log("No temperature data after reducing to max. This might indicate an issue with the collection or band selection.");
    console.log("C3");
    return;
  }

  // Calculate pixel count for the region to detect C2, using a larger scale for efficiency
  // For a single point, reducer.count() might not be the most relevant, but it's good practice.
  const pixelCountDict = await maxTempImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: furnaceCreek,
    scale: 1000, // Using a larger scale for stability on point reduction
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const validPixels = pixelCountDict['temperature_2m'];
  if (validPixels === 0 || validPixels === null) {
    console.log("No valid pixels found for temperature after processing.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels at location: ${validPixels}`);

  // 4. Calculation
  const maxTempCelsiusDict = await maxTempImage.reduceRegion({
    reducer: ee.Reducer.max(), // Use max reducer for the point as well, though mean might also work for a single point.
    geometry: furnaceCreek,
    scale: 1000, // ERA5-Land has ~9km resolution, so 1000m scale is fine.
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const maxTempCelsius = maxTempCelsiusDict['max'];

  // 5. Validation & Final Answer
  if (maxTempCelsius === null || isNaN(maxTempCelsius)) {
    console.log("Calculated maximum temperature is null or NaN.");
    console.log("C3");
    return;
  }

  console.log(`Max air temp on June 30, 2013, at Furnace Creek: ${maxTempCelsius.toFixed(2)} °C`);

  if (maxTempCelsius > 50) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
